begin;
create table if not exists public.organization_teams(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,description text,is_active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists public.organization_team_members(team_id uuid not null references public.organization_teams(id) on delete cascade,membership_id uuid not null references public.organization_members(id) on delete cascade,created_at timestamptz not null default now(),primary key(team_id,membership_id));
alter table public.organization_teams enable row level security; alter table public.organization_team_members enable row level security;
create policy "members read teams" on public.organization_teams for select using(exists(select 1 from public.organization_members m where m.organization_id=organization_teams.organization_id and m.user_id=auth.uid()));
create policy "admins manage teams" on public.organization_teams for all using(exists(select 1 from public.organization_members m where m.organization_id=organization_teams.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=organization_teams.organization_id and m.user_id=auth.uid() and m.role in('owner','admin')));
create policy "members read team membership" on public.organization_team_members for select using(exists(select 1 from public.organization_teams t join public.organization_members m on m.organization_id=t.organization_id where t.id=organization_team_members.team_id and m.user_id=auth.uid()));
commit;
